 // Stream relays events to one subscriber until the source ends or the subscriber leaves.
 type Stream struct {
 	src       Source
 	out       chan Event
 	done      chan struct{}
 	closeOnce sync.Once
 }

+// finish closes done once, whichever side ends the stream first.
+func (s *Stream) finish() {
+	s.closeOnce.Do(func() { close(s.done) })
+}
+
 func (s *Stream) run() {
+	defer s.finish()
 	for {
 		ev, err := s.src.Next()
 		if err != nil {
-			s.closeOnce.Do(func() { close(s.done) })
 			return
 		}
 		s.out <- ev
 	}
 }

+// Shutdown ends the stream when the subscriber disconnects.
+func (s *Stream) Shutdown() {
+	s.finish()
+}
+
 // Done is closed once the stream has ended.
 func (s *Stream) Done() <-chan struct{} {
 	return s.done
 }
